def build_shibuya_crossing():
    root_grp = "Shibuya_5Way_LowPoly_Root"
    if cmds.objExists(root_grp):
        cmds.delete(root_grp)
    root_grp = cmds.group(empty=True, name=root_grp)

    sg_map = {}
    for mat_name, m in SCENE_DATA["materials"].items():
        if cmds.objExists(mat_name):
            cmds.delete(mat_name)
        shd = cmds.shadingNode("lambert", asShader=True, name=mat_name)
        r, g, b = m["color"]
        er, eg, eb = m["emissive"]
        cmds.setAttr(shd + ".color", r, g, b, type="double3")
        cmds.setAttr(shd + ".incandescence", er, eg, eb, type="double3")
        sg = cmds.sets(renderable=True, noSurfaceShader=True, empty=True, name=mat_name + "SG")
        cmds.connectAttr(shd + ".outColor", sg + ".surfaceShader", force=True)
        sg_map[mat_name] = sg

    grp_map = {}
    for obj in SCENE_DATA["objects"]:
        gname = obj["group"]
        if gname not in grp_map:
            grp_map[gname] = cmds.group(empty=True, name=gname, parent=root_grp)

    for obj in SCENE_DATA["objects"]:
        pts = [om.MPoint(v[0], v[1], v[2]) for v in obj["vertices"]]
        poly_counts = [len(f) for f in obj["faces"]]
        poly_connects = [vi for f in obj["faces"] for vi in f]

        mesh_fn = om.MFnMesh()
        transform_obj = mesh_fn.create(pts, poly_counts, poly_connects)
        dag_fn = om.MFnDagNode(transform_obj)
        xform_name = cmds.rename(dag_fn.fullPathName(), obj["name"])
        cmds.parent(xform_name, grp_map[obj["group"]])
        cmds.sets(xform_name, edit=True, forceElement=sg_map[obj["material"]])
        cmds.polySoftEdge(xform_name, angle=60, constructionHistory=False)

    cmds.select(root_grp)
    cmds.viewFit()
    print("Shibuya 5-Way Low-Poly model created successfully!")

if __name__ == "__main__":
    build_shibuya_crossing()
